from pagination import paginate


def test_literal_issue_example():
    # range(1, 8) -> [1, 2, 3, 4, 5, 6, 7]; page 2, size 2 -> [3, 4]
    result = paginate(list(range(1, 8)), 2, 2)
    assert result == [3, 4]
    assert isinstance(result, list)


def test_first_page_is_one_based():
    assert paginate(list(range(1, 8)), 1, 2) == [1, 2]


def test_last_full_page():
    assert paginate(list(range(1, 8)), 3, 2) == [5, 6]


def test_partial_final_page():
    assert paginate(list(range(1, 8)), 4, 2) == [7]


def test_beyond_last_page_returns_empty():
    assert paginate(list(range(1, 8)), 5, 2) == []
    assert paginate(list(range(1, 8)), 100, 2) == []


def test_empty_input_preserved():
    assert paginate([], 1, 2) == []
    assert paginate([], 3, 5) == []


def test_invalid_page_preserved():
    assert paginate([1, 2, 3], 0, 2) == []
    assert paginate([1, 2, 3], -1, 2) == []


def test_invalid_page_size_preserved():
    assert paginate([1, 2, 3], 1, 0) == []
    assert paginate([1, 2, 3], 1, -5) == []


def test_page_size_larger_than_items():
    assert paginate([1, 2, 3], 1, 10) == [1, 2, 3]
    assert paginate([1, 2, 3], 2, 10) == []


def test_returns_new_list_not_mutating_input():
    items = [1, 2, 3, 4]
    result = paginate(items, 2, 2)
    assert result == [3, 4]
    assert result is not items
    assert items == [1, 2, 3, 4]

